// Builds ../ucp-webhook-echo.yml from echo.ps1, with _shared/postmark.ps1 pasted in by _shared/inject.js.
// Usage: node build.js          rewrite the generated file
//        node build.js --check  exit 1 if it is out of date
// Edit echo.ps1 (or _shared/postmark.ps1), never the generated .yml.
// Needs js-yaml: npm install in _shared, or set JS_YAML_PATH.
const fs = require('fs');
const path = require('path');
let y;
try { y = require('js-yaml'); } catch { try { y = require(path.join(__dirname, '..', '..', '_shared', 'node_modules', 'js-yaml')); } catch { y = require(process.env.JS_YAML_PATH); } }
const { injectText } = require(path.join(__dirname, '..', '..', '_shared', 'inject.js'));

const here = __dirname;
const root = path.join(here, '..');
const check = process.argv.includes('--check');
const read = (f) => fs.readFileSync(path.join(here, f), 'utf8').replace(/\r\n/g, '\n').trimEnd() + '\n';
const lib = (name) => `# >>> _shared/${name} (generated by _shared/inject.js; edit the source, not this block)\n# <<< _shared/${name}\n`;

const script = [
  '# =====================================================================',
  '#  UCP Webhook Echo - Email what arrived',
  '#  Emails the whole webhook body back, value by value, with unreplaced @tokens flagged. Writes nothing else.',
  '#  Secrets: Postmark-ServerToken, Postmark-FromEmail, optional Postmark-ApiUrl.',
  '#  Generated from ucp-webhook-echo/src. Edit the source, then run build.js.',
  '# =====================================================================',
  "$ErrorActionPreference = 'Stop'",
  'Set-StrictMode -Version Latest',
  '',
].join('\n') + '\n' + lib('postmark.ps1') + '\n# ---------- this step ----------\n' + read('echo.ps1');

const testInput = {
  toEmail: 'tester@examplemsp.com',
  ticketId: '12345',
  ticketSubject: 'UCP webhook test',
  companyName: 'Contoso',
  companyTenantId: '00000000-0000-0000-0000-000000000000',
  UserEmail: 'pat.lee@contoso.com',
  userIsAdmin: 'true',
  favouriteColour: 'Blue',
  notReplaced: '@SomeFieldId',
};

const wf = {
  automationsWorkflow: 1,
  name: 'UCP Webhook Echo',
  description:
    'Test tool for CloudRadial (UCP) Automations that call AutomationAI. Emails back everything the webhook delivered, value by value, ' +
    "and flags @tokens CloudRadial didn't replace, empty values and bodies that aren't valid JSON. Writes nothing else.",
  definition: {
    schemaVersion: 1,
    activities: [
      { id: 'start', name: 'Start', type: 'start', position: { x: 80, y: 120 }, properties: { webhookEnabled: false } },
      {
        id: 'node-echo', name: 'Email what arrived', type: 'powershell-script', position: { x: 320, y: 120 },
        properties: {
          script, timeoutSeconds: 120, retryCount: 0,
          parameters: [{ name: 'trigger', expression: '{{ nodes.trigger.output }}' }],
          aiExtensions: [],
          testInput: JSON.stringify(testInput, null, 2),
        },
      },
      { id: 'end', name: 'End', type: 'end', position: { x: 560, y: 120 } },
    ],
    connections: [
      { source: 'start', target: 'node-echo', sourceHandle: null },
      { source: 'node-echo', target: 'end', sourceHandle: null },
    ],
    startActivityId: 'start',
  },
};

const header = [
  '# CloudRadial AutomationAI - UCP Webhook Echo (test tool for portal Automations that call AutomationAI).',
  '# Generated by src/build.js. Edit src/echo.ps1, not this file.',
  '# Import on Workflows -> Import, then enable the webhook. See README.md.',
].join('\n');
const dumped = header + '\n' + y.dump(wf, { lineWidth: -1, noRefs: true });
const { text, blocks } = injectText(dumped, 'ucp-webhook-echo.yml', new Map());
if (blocks.length !== 1) throw new Error(`expected 1 _shared block, got ${blocks.length}`);
const back = y.load(text);
JSON.parse(back.definition.activities.find((a) => a.id === 'node-echo').properties.testInput);
if (back.definition.activities[0].properties.webhookEnabled !== false) throw new Error('webhook must ship off');
if (!back.definition.activities[1].properties.script.includes('function Send-PmMail')) throw new Error('postmark.ps1 not injected');

const out = path.join(root, 'ucp-webhook-echo.yml');
const was = fs.existsSync(out) ? fs.readFileSync(out, 'utf8').replace(/\r\n/g, '\n') : null;
const changed = was !== text;
console.log(`ucp-webhook-echo.yml: ${changed ? (check ? 'OUT OF DATE' : 'updated') : 'current'} (${text.length} bytes)`);
if (changed) {
  if (check) process.exit(1);
  fs.writeFileSync(out, text);
}
